 bg=[card("象岛文献（Elephantine Papyri）", "<p>埃及南部犹太军事殖民地的亚兰文书信（5世纪末），提到撒玛利亚省长参巴拉的儿子、耶路撒冷大祭司约哈难——与尼希米、玛拉基同一时代，也显示异族通婚与混合敬拜的普遍。</p>", "📜", "var(--gold)"), card("“省长”（pechah）", "<p>1:8 用的是波斯行政头衔；尼希米本人就是犹大省长（尼5:14）。</p>", "🏛️", "var(--blue)")],
