def body():
    hero = '''<section class="hero reveal"><div class="kick">TWELVE · III · PERSIAN ERA</div><h1>🏛️ 波斯时期的小先知</h1><p class="lead">哈该 · 撒迦利亚 · 玛拉基——被掳归回之后：重建圣殿、等候弥赛亚、对抗冷淡。旧约以一个应许结束：<b class=xr>“我要差遣我的使者在我前面预备道路。”</b></p>
<div class="chips"><span class="chip">📅 约主前520–430</span><span class="chip">🏛️ 波斯</span><span class="chip">📖 3 卷</span><span class="chip">🌉 通往新约</span></div></section>'''
    intro = H2("m3-intro", "📋", "本组概览", "var(--teal)") + '<p>这三卷与以斯拉记、尼希米记、以斯帖记同时代（参“旧约历史书”）。哈该与撒迦利亚鼓励建殿（拉5:1；6:14），玛拉基面对建殿之后的属灵冷淡。</p>' + group("minor3")
    return hero + intro + book(HAG) + book(ZEC) + book(MAL) + reading([96])
